337			return errors.New("name must be a nonempty relative slash-separated path")
338		}
339		clean := filepath.Clean(name)
340		if clean != name || strings.HasPrefix(clean, "../") {
341			return errors.New("name must be normalized and remain within the vault namespace")
342		}
343		return nil
344	}
