243	type fileID struct {
244		dev uint64
245		ino uint64
246	}
247	
248	func fileIDOf(info os.FileInfo) (fileID, bool) {
249		st, ok := info.Sys().(*syscall.Stat_t)
250		if !ok {
251			return fileID{}, false
252		}
253		return fileID{dev: uint64(st.Dev), ino: uint64(st.Ino)}, true
254	}
255	
256	// repoFileIDs collects the device/inode identity of every repository file an
257	// output must not be hard-linked to: the index, the lock, every content
258	// object (including unreferenced and temp-named ones, since replacing any file
259	// in the repository is forbidden), and every file under snapshots/. A
260	// directory that should be present but cannot be read is an error: protection
261	// must never silently narrow to the files that happened to be stat-able.
262	func (s *Store) repoFileIDs() (map[fileID]string, error) {
263		ids := map[fileID]string{}
264		// The index may legitimately be absent from a freshly initialized
265		// repository; the lock is created by the time an operation runs. Missing
266		// files simply contribute no identity.
267		if err := addIfExists(s.indexPath(), ids); err != nil {
268			return nil, err
269		}
270		if err := addIfExists(s.lockPath(), ids); err != nil {
271			return nil, err
272		}
273		objectsDir := filepath.Join(s.root, "objects")
274		if entries, err := os.ReadDir(objectsDir); err != nil {
275			if !errors.Is(err, os.ErrNotExist) {
276				return nil, fmt.Errorf("cannot read objects directory: %w", err)
277			}
278		} else {
279			for _, entry := range entries {
280				if err := addIfExists(filepath.Join(objectsDir, entry.Name()), ids); err != nil {
281					return nil, err
282				}
283			}
284		}
285		if err := filepath.WalkDir(s.snapshotsDir(), func(path string, d fs.DirEntry, err error) error {
286			if err != nil {
287				if errors.Is(err, os.ErrNotExist) {
288					return nil
289				}
290				return err
291			}
292			if d.IsDir() {
293				return nil
294			}
295			return addIfExists(path, ids)
296		}); err != nil {
297			return nil, err
298		}
299		return ids, nil
300	}
301	
302	// addIfExists records the identity of an existing file, ignoring only a
303	// genuinely missing path.
304	func addIfExists(path string, ids map[fileID]string) error {
305		info, err := os.Lstat(path)
306		if errors.Is(err, os.ErrNotExist) {
307			return nil
308		}
309		if err != nil {
310			return err
311		}
312		if id, ok := fileIDOf(info); ok {
313			ids[id] = path
314		}
315		return nil
316	}
317	
318	// downloadObject streams the verified object into a temporary file beside the
319	// output and renames it into place only after the complete bytes match the
320	// record. It never truncates or writes the output directly, and it never
321	// buffers the whole object in memory.
322	func (s *Store) downloadObject(entry Entry, absOut string, mode os.FileMode, pin *parentPin) error {
323		objPath := s.objectPath(entry.Digest)
324		info, err := os.Lstat(objPath)
325		if err != nil {
326			if errors.Is(err, os.ErrNotExist) {
327				return fmt.Errorf("object %s is missing", entry.Digest)
328			}
329			return fmt.Errorf("cannot stat object %s: %w", entry.Digest, err)
330		}
331		if info.Mode()&os.ModeSymlink != 0 {
332			return fmt.Errorf("object %s is a symbolic link", entry.Digest)
333		}
334		if !info.Mode().IsRegular() {
335			return fmt.Errorf("object %s is not a regular file", entry.Digest)
336		}
337	
338		in, err := os.Open(objPath)
339		if err != nil {
340			return fmt.Errorf("cannot read object %s: %w", entry.Digest, err)
341		}
342		defer in.Close()
343	
344		// The temporary file is created through the pinned parent descriptor; even
345		// if a path component is replaced by a symlink while the copy runs, the
346		// descriptor stays attached to the original directory, the temporary bytes
347		// land there and nowhere else, and the final rename is performed through
348		// the pin rather than the path.
349		tmp, tmpBase, err := createTempIn(pin, ".download-")
350		if err != nil {
351			return fmt.Errorf("cannot create temporary file for output: %w", err)
352		}
353		committed := false
354		defer func() {
355			if !committed {
356				removeTempIn(pin, tmpBase)
357			}
358		}()
359	
360		if err := tmp.Chmod(mode); err != nil {
361			tmp.Close()
362			return fmt.Errorf("cannot prepare output file: %w", err)
363		}
364		hash := sha256.New()
365		n, copyErr := io.Copy(io.MultiWriter(tmp, hash), in)
366		readErr := in.Close()
367		if copyErr != nil {
368			tmp.Close()
369			return fmt.Errorf("cannot read object %s: %w", entry.Digest, copyErr)
370		}
371		if readErr != nil {
372			tmp.Close()
373			return fmt.Errorf("cannot read object %s: %w", entry.Digest, readErr)
374		}
375		if n != entry.Size {
376			tmp.Close()
377			return fmt.Errorf("object %s is corrupted: content is %d bytes, record says %d", entry.Digest, n, entry.Size)
378		}
379		if actual := hex.EncodeToString(hash.Sum(nil)); actual != entry.Digest {
380			tmp.Close()
381			return fmt.Errorf("object %s is corrupted: content checksum is %s, want %s", entry.Digest, actual, entry.Digest)
382		}
383		if err := tmp.Sync(); err != nil {
384			tmp.Close()
385			return fmt.Errorf("cannot write output %q: %w", absOut, err)
386		}
387		if err := tmp.Close(); err != nil {
388			return fmt.Errorf("cannot write output %q: %w", absOut, err)
389		}
390		if err := s.commitOutput(pin, tmpBase, absOut); err != nil {
391			return err
392		}
393		committed = true
394		// Best-effort directory sync so the rename survives a crash; failure here
395		// does not undo an already atomic replacement.
396		_ = syncDirectory(pin.f)
397		return nil
398	}
399	
400	// commitOutput atomically replaces absOut with tmpPath through the pinned
401	// parent directory descriptor. Immediately before the rename it revalidates
402	// everything established by checkOutputSafe, since another process may have
403	// changed the filesystem while the content was being prepared:
404	//
405	//   - the pinned directory must still be the same physical directory reached
406	//     by its (fully resolved) path, must still be outside the repository, and
407	//     no path component may have become a symlink;
408	//   - an existing destination must still be missing or a regular file;
409	//   - an existing destination must still not be a hard link to any repository
410	//     file.
411	//
412	// If any condition no longer holds the rename is refused, so a parent swapped
413	// for a symlink into the repository can never cause the package to land on an
414	// index, snapshot, lock, or object.
415	func (s *Store) commitOutput(pin *parentPin, tmpPath, absOut string) error {
416		if err := s.pinStillPointsOutsideRepo(pin, absOut); err != nil {
417			return err
418		}
419		base := filepath.Base(absOut)
420		var st syscall.Stat_t
421		if err := fstatatNoFollow(pin.f.Fd(), base, &st); err != nil {
422			if !errors.Is(err, os.ErrNotExist) {
423				return fmt.Errorf("output %q: cannot inspect destination: %w", absOut, err)
424			}
425		} else {
426			switch st.Mode & syscall.S_IFMT {
427			case syscall.S_IFLNK:
428				return fmt.Errorf("output %q is a symbolic link", absOut)
429			case syscall.S_IFREG:
430			default:
431				return fmt.Errorf("output %q is not a regular file", absOut)
432			}
433			outID := fileID{dev: uint64(st.Dev), ino: uint64(st.Ino)}
434			ids, err := s.repoFileIDs()
435			if err != nil {
436				return fmt.Errorf("output %q: cannot verify it is not linked to a repository file: %w", absOut, err)
437			}
438			for id, repoPath := range ids {
439				if id == outID {
440					return fmt.Errorf("output %q is a hard link to repository file %q", absOut, repoPath)
441				}
442			}
443		}
444	
445		if err := renameAt(pin.f.Fd(), filepath.Base(tmpPath), pin.f.Fd(), base); err != nil {
446			return fmt.Errorf("cannot write output %q: %w", absOut, err)
447		}
448		return nil
449	}
450	
451	// pinStillPointsOutsideRepo revalidates the pinned output directory at commit
452	// time. It must remain the exact directory the pin was opened on (compared by
453	// device/inode), its path must still resolve with no symlink components to the
454	// same physical directory, and that directory must still lie outside the
455	// resolved repository tree.
456	func (s *Store) pinStillPointsOutsideRepo(pin *parentPin, absOut string) error {
457		var pinStat syscall.Stat_t
458		if err := syscall.Fstat(int(pin.f.Fd()), &pinStat); err != nil {
459			return fmt.Errorf("output %q: cannot verify destination directory: %w", absOut, err)
460		}
461		info, err := os.Lstat(pin.path)
462		if err != nil {
463			return fmt.Errorf("output %q: destination directory is no longer accessible: %w", absOut, err)
464		}
465		if info.Mode()&os.ModeSymlink != 0 || !info.IsDir() {
466			return fmt.Errorf("output %q is unsafe: destination directory was replaced", absOut)
467		}
468		if id, ok := fileIDOf(info); !ok || id.dev != uint64(pinStat.Dev) || id.ino != uint64(pinStat.Ino) {
469			return fmt.Errorf("output %q is unsafe: destination directory was replaced", absOut)
470		}
471		resolved, err := filepath.EvalSymlinks(pin.path)
472		if err != nil {
473			return fmt.Errorf("output %q: destination directory is no longer accessible: %w", absOut, err)
474		}
475		if resolved != pin.path {
476			return fmt.Errorf("output %q is unsafe: destination directory now resolves through a symbolic link", absOut)
477		}
478		absRoot, err := filepath.Abs(s.root)
479		if err != nil {
480			return fmt.Errorf("cannot resolve repository root: %w", err)
481		}
482		resolvedRoot, err := filepath.EvalSymlinks(absRoot)
483		if err != nil {
484			return fmt.Errorf("cannot resolve repository root: %w", err)
485		}
486		if isWithin(resolvedRoot, pin.path) {
487			return fmt.Errorf("output %q is unsafe: destination directory is inside the repository", absOut)
488		}
489		return nil
490	}
491	
492	// atSymlinkNoFollow is the AT_SYMLINK_NOFOLLOW flag for fstatat.
493	const atSymlinkNoFollow = 0x100
494	
495	// fstatatNoFollow stats a path relative to dirfd without following a terminal
496	// symlink. A missing file is reported with os.ErrNotExist.
497	func fstatatNoFollow(dirfd uintptr, name string, st *syscall.Stat_t) error {
498		pathPtr, err := syscall.BytePtrFromString(name)
499		if err != nil {
500			return err
501		}
502		_, _, errno := syscall.Syscall6(syscall.SYS_FSTATAT, dirfd, uintptr(unsafe.Pointer(pathPtr)),
503			uintptr(unsafe.Pointer(st)), uintptr(atSymlinkNoFollow), 0, 0)
504		if errno != 0 {
505			if errno == syscall.ENOENT {
506				return os.ErrNotExist
507			}
508			return errno
509		}
510		return nil
511	}
512	
513	// renameAt renames within directories given by file descriptors, so the
514	// operation cannot be redirected by a later path-component replacement.
515	func renameAt(oldDir uintptr, oldName string, newDir uintptr, newName string) error {
516		oldPtr, err := syscall.BytePtrFromString(oldName)
517		if err != nil {
518			return err
519		}
520		newPtr, err := syscall.BytePtrFromString(newName)
521		if err != nil {
522			return err
523		}
524		_, _, errno := syscall.Syscall6(syscall.SYS_RENAMEAT,
525			oldDir, uintptr(unsafe.Pointer(oldPtr)),
526			newDir, uintptr(unsafe.Pointer(newPtr)), 0, 0)
527		if errno != 0 {
528			return errno
529		}
530		return nil
531	}
532	
533	// createTempIn creates a new, exclusively owned temporary file with a unique
534	// name directly inside the pinned directory (via openat, never by path) and
535	// returns the open file together with its basename for the commit rename.
536	func createTempIn(pin *parentPin, prefix string) (*os.File, string, error) {
537		var random [16]byte
538		if _, err := rand.Read(random[:]); err != nil {
539			return nil, "", err
540		}
541		for i := 0; i < 100; i++ {
542			if i > 0 {
543				if _, err := rand.Read(random[:]); err != nil {
544					return nil, "", err
545				}
546			}
547			name := prefix + hex.EncodeToString(random[:])
548			fd, errno := syscall.Openat(int(pin.f.Fd()), name,
549				syscall.O_CREAT|syscall.O_EXCL|syscall.O_WRONLY|syscall.O_CLOEXEC|syscall.O_NOFOLLOW, 0o600)
550			if errno == syscall.EEXIST {
551				continue
552			}
553			if errno != nil {
554				return nil, "", errno
555			}
556			return os.NewFile(uintptr(fd), filepath.Join(pin.path, name)), name, nil
557		}
558		return nil, "", errors.New("could not find an unused temporary file name")
559	}
560	
561	// removeTempIn unlinks a staged temporary file through the pinned directory.
562	func removeTempIn(pin *parentPin, name string) {
563		namePtr, err := syscall.BytePtrFromString(name)
564		if err != nil {
565			return
566		}
567		_, _, _ = syscall.Syscall6(syscall.SYS_UNLINKAT, pin.f.Fd(),
568			uintptr(unsafe.Pointer(namePtr)), 0, 0, 0, 0)
569	}
570	
571	func syncDirectory(dir *os.File) error {
572		return dir.Sync()
573	}
574

