1	package vault
2	
3	import (
4		"bytes"
5		"fmt"
6		"os"
7		"path/filepath"
8		"sync"
9		"testing"
10	)
11	
12	// TestVerifyConcurrentPutAndGC races Verify against another Store instance
13	// (a stand-in for a second process: each operation takes its own flock on the
14	// shared lock file) that continuously overwrites every artifact and collects
15	// the superseded objects. Every Verify pass must observe one complete
16	// generation of the repository: it must never see an object vanish because a
17	// put+gc cycle landed between reading the name mapping and reading the
18	// objects that mapping referenced.
19	func TestVerifyConcurrentPutAndGC(t *testing.T) {
20		root := filepath.Join(t.TempDir(), "vault")
21		store := New(root)
22		if err := store.Init(); err != nil {
23			t.Fatal(err)
24		}
25		const artifacts = 12
26		const payloadSize = 2 << 20 // large enough that a pass reads for a while
27		srcDir := t.TempDir()
28		writeSource := func(iter, i int) string {
29			path := filepath.Join(srcDir, fmt.Sprintf("src-%d-%d.bin", iter, i))
30			content := bytes.Repeat([]byte{byte(iter), byte(i)}, payloadSize)
31			if err := os.WriteFile(path, content, 0o644); err != nil {
32				t.Fatal(err)
33			}
34			return path
35		}
36		name := func(i int) string { return fmt.Sprintf("releases/artifact-%d.bin", i) }
37		for i := 0; i < artifacts; i++ {
38			if _, err := store.Put(name(i), writeSource(0, i)); err != nil {
39				t.Fatal(err)
40			}
41		}
42	
43		stop := make(chan struct{})
44		var wg sync.WaitGroup
45		wg.Add(1)
